import { act, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { Component, Suspense } from 'react';
import { expect, it } from 'vitest';
import { UserCard } from './Solution';

interface User {
  id: string;
  name: string;
}

/** 受控 API 替身：谁先返回由用例决定，因此能构造"先发后到"。 */
function makeApi() {
  const pending: { id: string; resolve: (u: User) => void; reject: (e: unknown) => void }[] = [];
  const fetchUser = (id: string): Promise<User> => {
    let resolve: (u: User) => void = () => undefined;
    let reject: (e: unknown) => void = () => undefined;
    const p = new Promise<User>((res, rej) => {
      resolve = res;
      reject = rej;
    });
    p.catch(() => undefined);
    pending.push({ id, resolve: (u) => resolve(u), reject: (e) => reject(e) });
    return p;
  };
  return { pending, fetchUser };
}

class Boundary extends Component<{ children: React.ReactNode }, { err: unknown }> {
  state = { err: null as unknown };
  static getDerivedStateFromError(error: unknown) {
    return { err: error };
  }
  render() {
    if (this.state.err !== null) {
      return <button data-testid="reset" onClick={() => this.setState({ err: null })}>caught</button>;
    }
    return this.props.children;
  }
}

function App({ userId, api }: { userId: string; api: ReturnType<typeof makeApi> }) {
  return (
    <Boundary>
      <Suspense fallback={<span data-testid="fb">loading</span>}>
        <UserCard userId={userId} fetchUser={api.fetchUser} />
      </Suspense>
    </Boundary>
  );
}

/**
 * 用例驱动工具。两个测试环境细节写在测试侧，与考生实现无关：
 * 1) prime()：jsdom 里 React 调度没有 MessageChannel，挂起中的 boundary 需要"再跑一轮 render +
 *    让出一个宏任务"才会把已解析的 promise 提交上屏；until() 就是把这个动作做成有界轮询；
 * 2) 收敛一律靠轮询真实 DOM/调用次数，不猜墙钟。
 */
function mount(userId: string) {
  const api = makeApi();
  const tree = (id: string) => <App userId={id} api={api} />;
  let current = userId;
  const { rerender } = render(tree(current));
  const prime = (times = 1) => {
    for (let i = 0; i < times; i += 1) rerender(tree(current));
  };
  const spin = async () => {
    await act(async () => {
      await new Promise((r) => setTimeout(r, 0));
    });
  };
  const until = async (check: () => boolean) => {
    for (let i = 0; i < 30; i += 1) {
      prime();
      await spin();
      if (check()) return;
    }
  };
  const go = async (id: string) => {
    current = id;
    rerender(tree(current));
    await spin();
  };
  const settle = async (index: number, user: User) => {
    act(() => api.pending[index].resolve(user));
    await spin();
  };
  const fail = async (index: number, error: unknown) => {
    act(() => api.pending[index].reject(error));
    await spin();
  };
  const shown = async (text: string) => {
    await until(() => screen.queryByTestId('name')?.textContent === text);
    expect(screen.getByTestId('name').textContent).toBe(text);
  };
  const requests = async (count: number) => {
    await until(() => api.pending.length === count);
    expect(api.pending.length).toBe(count);
  };
  const caught = async () => {
    await until(() => screen.queryByTestId('reset')?.textContent === 'caught');
    expect(screen.getByTestId('reset').textContent).toBe('caught');
  };
  return { api, prime, spin, go, settle, fail, shown, requests, caught };
}

it('同一 id 重复渲染只请求一次', async () => {
  const h = mount('u1');
  h.prime(4);
  expect(h.api.pending.length).toBe(1);
  await h.settle(0, { id: 'u1', name: 'Ada' });
  await h.shown('Ada');
  h.prime(4);
  expect(h.api.pending.length).toBe(1);
  expect(screen.getAllByTestId('name').length).toBe(1);
});

it('两个实例共享同一条 promise 不各发一次', async () => {
  const api = makeApi();
  const pair = () => (
    <div>
      <App userId="u1" api={api} />
      <App userId="u1" api={api} />
    </div>
  );
  const { rerender } = render(pair());
  rerender(pair());
  expect(api.pending.length).toBe(1);
  act(() => api.pending[0].resolve({ id: 'u1', name: 'Ada' }));
  for (let i = 0; i < 30; i += 1) {
    rerender(pair());
    await act(async () => {
      await new Promise((r) => setTimeout(r, 0));
    });
    if (screen.queryAllByTestId('name').length === 2) break;
  }
  expect(screen.getAllByTestId('name').map((el) => el.textContent)).toEqual(['Ada', 'Ada']);
  expect(api.pending.length).toBe(1);
});

it('切换 id 时旧响应晚到不脏渲染', async () => {
  const h = mount('u1');
  await h.settle(0, { id: 'u1', name: 'Ada' });
  await h.shown('Ada');
  await h.go('u2');
  await h.requests(2);
  expect(h.api.pending[1].id).toBe('u2');
  await h.go('u1');
  expect(h.api.pending.length).toBe(2);
  await h.shown('Ada');
  await h.settle(1, { id: 'u2', name: 'Grace' });
  await h.shown('Ada');
});

it('刷新换 promise 实例但保留子树状态', async () => {
  const h = mount('u1');
  await h.settle(0, { id: 'u1', name: 'Ada' });
  await h.shown('Ada');
  fireEvent.click(screen.getByTestId('bump'));
  expect(screen.getByTestId('local').textContent).toBe('1');
  fireEvent.click(screen.getByTestId('refresh'));
  await h.spin();
  expect(screen.getByTestId('name').textContent).toBe('Ada');
  await h.requests(2);
  await h.settle(1, { id: 'u1', name: 'Ada Lee' });
  await h.shown('Ada Lee');
  expect(screen.getByTestId('local').textContent).toBe('1');
});

it('失败冒泡到错误边界且不触发自动重试风暴', async () => {
  const h = mount('u1');
  await h.fail(0, new Error('500'));
  await h.caught();
  expect(h.api.pending.length).toBe(1);
  await h.go('u2');
  fireEvent.click(screen.getByTestId('reset'));
  await h.requests(2);
  await h.settle(1, { id: 'u2', name: 'Grace' });
  await h.shown('Grace');
});

it('空 id 不发请求直接渲染 not-found', () => {
  const h = mount('');
  expect(h.api.pending.length).toBe(0);
  expect(screen.getByTestId('name').textContent).toBe('not-found');
});

