import { use, useState, useTransition } from 'react';
import type { ReactNode } from 'react';

export interface User {
  id: string;
  name: string;
}

type FetchUser = (id: string) => Promise<User>;

/**
 * promise 缓存以 fetchUser 函数身份为第一层 key（WeakMap 不泄漏），
 * 第二层是 id + "@" + version。失败结果同样留在这一格里（渲染路径绝不自动重发），
 * 恢复靠换 key：切 id 或刷新 version。
 */
const cache = new WeakMap<FetchUser, Map<string, Promise<User>>>();

function cachedPromise(fetchUser: FetchUser, id: string, cacheKey: string): Promise<User> {
  let byKey = cache.get(fetchUser);
  if (!byKey) {
    byKey = new Map();
    cache.set(fetchUser, byKey);
  }
  const hit = byKey.get(cacheKey);
  if (hit) return hit;
  // 失败也留在这一格缓存里：渲染路径绝不"发现没有就再发一次"，否则 wake 之后就是请求风暴。
  // 恢复靠换 key（切 id / 刷新 version），不靠自动重试。
  const p = fetchUser(id);
  byKey.set(cacheKey, p);
  return p;
}

export function UserCard({ userId, fetchUser }: { userId: string; fetchUser: FetchUser }): ReactNode {
  const [version, setVersion] = useState(0);
  const [local, setLocal] = useState(0);
  const [isPending, startRefresh] = useTransition();

  if (!userId) return <span data-testid="name">not-found</span>;

  const cacheKey = userId + '@' + version;
  // use() 幂等：同一个 cacheKey 反复 render 读到的是同一 promise 实例，不会反复挂起
  const user = use(cachedPromise(fetchUser, userId, cacheKey));

  return (
    <>
      <span data-testid="name">{user.name}</span>
      <span data-testid="local">{local}</span>
      <span data-testid="refreshing">{isPending ? 'yes' : 'no'}</span>
      <button data-testid="bump" onClick={() => setLocal((n) => n + 1)}>bump</button>
      <button
        data-testid="refresh"
        onClick={() => {
          startRefresh(async () => {
            const next = version + 1;
            // 先把新 promise 拉到就绪再换 key：整棵树不退回 fallback，本地状态与 DOM 内部状态都保住
            await cachedPromise(fetchUser, userId, userId + '@' + next);
            setVersion(next);
          });
        }}
      >
        refresh
      </button>
    </>
  );
}

