import { useEffect, useState } from 'react';

export function UserCard({ userId, fetchUser }: { userId: string; fetchUser: (id: string) => Promise<{ id: string; name: string }> }) {
  const [user, setUser] = useState(null);
  const [local, setLocal] = useState(0);
  useEffect(() => {
    fetchUser(userId).then((u) => setUser(u));
  }, [userId, fetchUser]);
  return (
    <>
      <span data-testid="name">{user ? user.name : 'loading'}</span>
      <span data-testid="local">{local}</span>
      <button data-testid="bump" onClick={() => setLocal((n) => n + 1)}>bump</button>
      <button data-testid="refresh">refresh</button>
    </>
  );
}
